"""Lossless stdlib compressor. Usage: compress.py [--decompress] INPUT OUTPUT."""
import bz2
import sys
from pathlib import Path


def compress(data):
    return bz2.compress(data, compresslevel=9)


def decompress(data):
    return bz2.decompress(data)


def main():
    args = sys.argv[1:]
    decode = args[:1] == ['--decompress']
    if decode:
        args = args[1:]
    if len(args) != 2:
        raise SystemExit('usage: compress.py [--decompress] INPUT OUTPUT')
    data = Path(args[0]).read_bytes()
    Path(args[1]).write_bytes(decompress(data) if decode else compress(data))


if __name__ == '__main__':
    main()
